def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def log(event, **values):
    print(json.dumps({"event": event, **values}), flush=True)


def sha256(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda: stream.read(8 << 20), b""):
            digest.update(block)
    return digest.hexdigest()


def pinned(path, expected):
    require(Path(path).is_file() and sha256(path) == expected, "SHA256 mismatch: " + str(path))
    return Path(path)


def unpack(destination):
    raw = base64.b64decode(PAYLOAD_B64, validate=True)
    require(hashlib.sha256(raw).hexdigest() == PAYLOAD_SHA, "Embedded archive hash mismatch")
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        require(len(archive.namelist()) == len(EMBEDDED_FILES), "Embedded archive duplicates")
        require(set(archive.namelist()) == set(EMBEDDED_FILES), "Unexpected embedded files")
        for name, info in EMBEDDED_FILES.items():
            data = archive.read(name)
            require(len(data) == info["bytes"] and hashlib.sha256(data).hexdigest() == info["sha256"], name)
            target = destination / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)


def valid_members(archive):
    entries = archive.infolist()
    names = [i.filename for i in entries]
    require(len(names) == 18 and len(set(names)) == 18 and set(names) == EXPECTED_NAMES,
            "Expected precisely the pinned 18-member portfolio")
    for info in entries:
        path = PurePosixPath(info.filename)
        require(not path.is_absolute() and ".." not in path.parts and "\\" not in info.filename,
                "Unsafe archive path")
        require(not info.is_dir() and not (info.flag_bits & 1), "Directories/encrypted members are not allowed")
        require(not stat.S_ISLNK(info.external_attr >> 16), "Symlink member is not allowed")
    return entries


def copy_stream(incoming, outgoing):
    digest = hashlib.sha256()
    size = 0
    for block in iter(lambda: incoming.read(8 << 20), b""):
        outgoing.write(block)
        digest.update(block)
        size += len(block)
    return {"sha256": digest.hexdigest(), "bytes": size}


def package_preserving_members(baseline, candidate, destination):
    require(not destination.exists(), "Output ZIP already exists")
    require(destination.resolve() != baseline.resolve(), "Cannot overwrite the original ZIP")
    records = []
    with zipfile.ZipFile(baseline) as old, zipfile.ZipFile(destination, "x", allowZip64=True) as new:
        for info in valid_members(old):
            if info.filename == "dqi.kmb":
                with candidate.open("rb") as src, new.open(info, "w", force_zip64=True) as dst:
                    after = copy_stream(src, dst)
                records.append({"member": info.filename, "before_sha256": BASE_DQI_SHA, "after": after})
            else:
                with old.open(info) as src, new.open(info, "w", force_zip64=True) as dst:
                    after = copy_stream(src, dst)
                records.append({"member": info.filename, "before_sha256": after["sha256"], "after": after})
        new.comment = old.comment
    with zipfile.ZipFile(destination) as check:
        valid_members(check)
        for record in records:
            digest = hashlib.sha256()
            size = 0
            with check.open(record["member"]) as src:
                for block in iter(lambda: src.read(8 << 20), b""):
                    digest.update(block)
                    size += len(block)
            require(digest.hexdigest() == record["after"]["sha256"] and size == record["after"]["bytes"],
                    "Written member failed integrity check: " + record["member"])
    return records


def main():
    started = time.monotonic()
    input_root, output = Path("/kaggle/input"), Path("/kaggle/working")
    require(input_root.is_dir() and output.is_dir(), "Run this in a Kaggle notebook")
    destination = output / "submission.zip"
    require(not destination.exists(), "Use a fresh run; submission.zip already exists")
    scratch = Path(tempfile.mkdtemp(prefix="gvqcc-promote-", dir="/tmp"))
    source = scratch / "source"
    source.mkdir()
    unpack(source)
    all_files = sorted(p for p in input_root.rglob("*") if p.is_file())
    baseline = next((p for p in all_files if p.name == "submission.zip" and sha256(p) == BASE_ZIP_SHA), None)
    require(baseline is not None, "Attach the exact v1 notebook output (scriptVersionId 369610226)")
    competition = None
    for verifier in (p for p in all_files if p.name == "verify_submission_dqi.py"):
        possible = verifier.parents[2]
        if all((possible / name).is_file() for name in OFFICIAL_PINS):
            if all(sha256(possible / name) == digest for name, digest in OFFICIAL_PINS.items()):
                competition = possible
                break
    require(competition is not None, "Pinned competition engine/verifier is missing")
    original = scratch / "v1_dqi.kmb"
    with zipfile.ZipFile(baseline) as archive:
        valid_members(archive)
        with archive.open("dqi.kmb") as src, original.open("xb") as dst:
            extracted = copy_stream(src, dst)
    require(extracted["sha256"] == BASE_DQI_SHA, "v1 DQI does not match the pinned circuit")
    log("inputs_verified", baseline_zip=BASE_ZIP_SHA, dqi=BASE_DQI_SHA, competition=str(competition))
    candidate = scratch / "v2_dqi.kmb"
    factor_path = output / "dqi_input_factor384.json"
    require(not factor_path.exists(), "Factor report already exists")
    environment = dict(os.environ)
    environment["PYTHONUNBUFFERED"] = "1"
    environment["PYTHONPATH"] = os.pathsep.join((str(competition / "kickmix"), str(source)))
    command = [sys.executable, "-u", str(source / "dqi_ccx_input_factor.py"), str(original),
               "--output", str(candidate), "--report", str(factor_path), "--window", "256", "--seconds", "1800"]
    subprocess.run(command, env=environment, check=True, timeout=1900)
    factor = json.loads(factor_path.read_text())
    require(factor.get("status") == "COMPLETE" and factor.get("input_sha256") == BASE_DQI_SHA,
            "Factor scan did not complete against v1")
    require(factor.get("output_sha256") == TARGET_DQI_SHA and factor.get("static_ccx_reduction") == 384
            and factor.get("total_current_block_rewrites") == 384, "384-rewrite result mismatch")
    require(len(factor.get("blocks", [])) == 16, "Expected 16 proved blocks")
    for block in factor["blocks"]:
        require(block.get("condition_stack_depth") == 0 and block.get("verified_rewrite_count") == 24,
                "Unexpected block conditions or rewrite count")
        require((block.get("exact_polynomial_proof") or {}).get("status") == "PASS", "Block proof failed")
    pinned(candidate, TARGET_DQI_SHA)
    log("candidate_generated", sha256=TARGET_DQI_SHA, additional_ccx_reduction=384)
    result_path = output / "dqi_full_verification.json"
    require(not result_path.exists(), "Verification report already exists")
    command = [sys.executable, "-u", str(source / "verify_dqi_candidate.py"), str(candidate),
               "--verifier", str(competition / "verifiers/dqi/verify_submission_dqi.py"),
               "--output", str(result_path), "--shots", "102400", "--batch-size", "256", "--progress-every", "20"]
    subprocess.run(command, env=environment, check=True, timeout=7200)
    result = json.loads(result_path.read_text())
    require(result.get("status") == "PASS" and result.get("verified_shots") == 102400, "Full DQI did not pass")
    require(result.get("circuit_sha256") == TARGET_DQI_SHA and result.get("log2_delta") == -128,
            "Verification circuit/confidence mismatch")
    require(result.get("seed") is None and result.get("salt") == "" and result.get("max_workers") == 1,
            "Verification settings mismatch")
    require(result.get("verifier_sha256") == OFFICIAL_PINS["verifiers/dqi/verify_submission_dqi.py"],
            "Wrong verifier was loaded")
    require(result.get("kickmix_binary_sha256") == OFFICIAL_PINS["kickmix/kickmix.so"], "Wrong engine was loaded")
    pinned(candidate, TARGET_DQI_SHA)
    staged_zip = scratch / "submission.zip"
    records = package_preserving_members(baseline, candidate, staged_zip)
    require(len(records) == 18 and sum(r["member"] != "dqi.kmb" for r in records) == 17, "Portfolio mismatch")
    archive_sha = sha256(staged_zip)
    with staged_zip.open("rb") as src, destination.open("xb") as dst:
        copied = copy_stream(src, dst)
    require(copied["sha256"] == archive_sha, "Final ZIP copy mismatch")
    receipt = {
        "status": "OFFICIAL_DQI_FULL_PASS_AND_PACKAGED", "kaggle_submission_performed": False,
        "variant": "480gauge128", "source_notebook": V1_SOURCE, "source_zip": str(baseline),
        "source_zip_sha256": BASE_ZIP_SHA, "source_dqi_sha256": BASE_DQI_SHA,
        "candidate_dqi_sha256": TARGET_DQI_SHA, "submission_zip_sha256": archive_sha,
        "submission_zip_bytes": destination.stat().st_size, "non_dqi_members_preserved": 17,
        "unchanged_tasks": "invsqrt and dfthcsos bytes retained from v1, not rerun in this promotion",
        "verification_sha256": sha256(result_path), "factor_report_sha256": sha256(factor_path),
        "verification": result, "members": records, "official_pins": OFFICIAL_PINS,
        "embedded_source_manifest": EMBEDDED_FILES, "embedded_archive_sha256": PAYLOAD_SHA,
        "seconds": time.monotonic() - started,
    }
    prior_notice = baseline.parent / "SOURCE_NOTICE.md"
    if prior_notice.is_file():
        shutil.copyfile(prior_notice, output / "SOURCE_NOTICE_V1.md")
        receipt["v1_source_notice_sha256"] = sha256(prior_notice)
    (output / "promotion_receipt.json").write_text(json.dumps(receipt, indent=2) + "\n")
    notice = "GVQCC v1-to-v2 promotion. Original notebook: " + V1_SOURCE + "\n\n"
    notice += "Only DQI changed. Its full official verification is dqi_full_verification.json.\n"
    notice += "The other 17 submission members retain exactly the v1 uncompressed bytes.\n"
    notice += "No Kaggle competition submission is performed by this worker.\n\n"
    notice += (source / "NOTICE.md").read_text()
    (output / "SOURCE_NOTICE.md").write_text(notice)
    for name in ("third_party/Qualtran_Apache_2.0.txt", "third_party/Syed_DQI_Apache_2.0.txt"):
        shutil.copyfile(source / name, output / Path(name).name)
    log("complete", submission_zip_sha256=archive_sha, candidate_sha256=TARGET_DQI_SHA,
        official_score=result.get("score"), shots=result["verified_shots"], preserved_other_members=17,
        seconds=receipt["seconds"])


if __name__ == "__main__":
    main()
